<?php
namespace App\Http\Controllers;
use App\Services\AuditLogger;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Gate;
use Inertia\Inertia;
class BroadcastController {
 public function __construct(private AuditLogger $audit) {}
 public function index(){Gate::authorize('synapse-users-moderate');$items=DB::table('broadcasts')->orderByDesc('id')->paginate(30);$items->getCollection()->transform(function($b){$b->total=DB::table('broadcast_recipients')->where('broadcast_id',$b->id)->count();$b->sent=DB::table('broadcast_recipients')->where('broadcast_id',$b->id)->where('status','sent')->count();return $b;});return Inertia::render('Broadcast/Index',['broadcasts'=>$items]);}
 public function store(Request $r){Gate::authorize('synapse-users-moderate');$data=$r->validate(['message'=>'required|string|max:4000','audience'=>'required|in:all,category,selected','activity_category'=>'nullable|in:heavy_active,active,low_active,dormant,suspicious','recipients'=>'nullable|array|max:5000','recipients.*'=>'string|max:255','throttle_ms'=>'required|integer|min:100|max:60000','max_retries'=>'required|integer|min:0|max:10','confirmed'=>'accepted']);$recipients=match($data['audience']){'selected'=>array_values(array_unique($data['recipients']??[])),'category'=>DB::table('user_activity')->where('category',$data['activity_category'])->pluck('user_id')->all(),default=>DB::table('user_activity')->pluck('user_id')->all()};if(count($recipients)===0)return back()->withErrors(['recipients'=>'هیچ گیرنده‌ای برای این انتخاب پیدا نشد.']);$id=DB::table('broadcasts')->insertGetId(['message'=>$data['message'],'msgtype'=>'m.text','audience'=>$data['audience'],'activity_category'=>$data['activity_category']??null,'throttle_ms'=>$data['throttle_ms'],'max_retries'=>$data['max_retries'],'status'=>'queued','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);foreach(array_chunk($recipients,500) as $chunk){DB::table('broadcast_recipients')->insert(array_map(fn($user)=>['broadcast_id'=>$id,'user_id'=>$user,'status'=>'pending','created_at'=>now(),'updated_at'=>now()],$chunk));}$this->audit->record($r,'broadcast.create','broadcast',(string)$id,['audience'=>$data['audience'],'activity_category'=>$data['activity_category']??null,'recipient_count'=>count($recipients),'throttle_ms'=>$data['throttle_ms']]);return redirect()->route('broadcasts.show',$id)->with('success','پیام در صف ارسال قرار گرفت.');}
 public function show(int $id){Gate::authorize('synapse-users-moderate');$broadcast=DB::table('broadcasts')->find($id);abort_unless($broadcast,404);$recipients=DB::table('broadcast_recipients')->where('broadcast_id',$id)->orderBy('id')->paginate(100);return Inertia::render('Broadcast/Show',['broadcast'=>$broadcast,'recipients'=>$recipients]);}
}
